<!DOCTYPE html><html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Checkout | ShopNest</title><link rel="stylesheet" href="style.css"></head><body><?php require __DIR__.'/../layout/header.php'; ?><main class="container cart-page"><div class="page-head"><h1>Checkout</h1><p>Confirm your delivery and payment information.</p></div><div class="panel" style="max-width:650px;margin:auto"><?php if($success): ?><div class="empty"><h1>Order placed!</h1><p>Thank you for shopping with ShopNest. Your order number is <strong>#<?= $orderId ?></strong>.</p><a class="btn btn-primary" href="orders.php">View Order</a></div><?php elseif($total<=0): ?><div class="empty"><h1>No items to checkout</h1><a class="btn btn-primary" href="index.php">Shop Now</a></div><?php else: ?><h2>Order Total: Tk:<?= number_format($total,2) ?></h2><?php if($error): ?><p class="error-message"><?= htmlspecialchars($error) ?></p><?php endif; ?><form method="post"><div class="field"><label>Full Name</label><input name="name" required value="<?= htmlspecialchars($_POST['name']??$user['name']) ?>"></div><div class="field"><label>Address</label><textarea name="address" required><?= htmlspecialchars($_POST['address']??$user['address']) ?></textarea></div><div class="field"><label>Phone</label><input name="phone" required value="<?= htmlspecialchars($_POST['phone']??$user['phone']) ?>"></div><div class="field"><label>Payment Method</label><select name="method"><option>Cash on Delivery</option><option>Card</option><option>Mobile Banking</option></select></div><button class="btn btn-primary">Place Order</button></form><?php endif; ?></div></main><?php require __DIR__.'/../layout/footer.php'; ?></body></html>
